#!/usr/bin/env python3
# SPDX-License-Identifier: Apache-2.0
"""Keep source-SHA normalization bounded and its artifact guard mandatory."""
import re
import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parents[2]
PLUGIN = "build-logic/src/main/kotlin/openbank.test-provenance.gradle.kts"
SERVICE = "build-logic/src/main/kotlin/openbank.quarkus-service.gradle.kts"
HELPER = "build-logic/src/main/kotlin/com/openbank/buildlogic/BuildFactsInputs.kt"


def violations(plugin, service, helper):
    errors = []
    if re.findall(r'ignore\("([^"]+)"\)', plugin) != ["docs/00-build.md", "openbank-service-build.properties"]:
        errors.append("normalize only the two explicitly fingerprinted build-facts resources")
    if 'buildFactsInputs(classpath.files, normalizeCommit = name == "test" && !brokerConfigured)' not in plugin:
        errors.append("Test inputs must retain every non-SHA build-facts byte")
    if ('systemProperties.keys.any' not in plugin or any(
            f'"{key}"' not in plugin for key in
            ("pactbroker.url", "pact.provider.version", "pact.verifier.publishResults"))):
        errors.append("broker-configured ordinary tests must retain full metadata")
    if 'id("openbank.test-provenance")' not in service:
        errors.append("services must apply the tested normalization plugin")
    if not re.search(r'tasks.withType<QuarkusBuildTask>\(\).configureEach\s*\{\s*inputs.property\("unfilteredBuildFacts", providers.provider\s*\{\s*buildFactsInputs\(classpath.files, normalizeCommit = false\)', service):
        errors.append("Quarkus artifact keys must retain the full source SHA and metadata")
    for path in ("docs/00-build.md", "openbank-service-build.properties"):
        if f'== generatedServiceDocs.get().asFile.resolve("{path}").readText()' not in service:
            errors.append(f"packaged {path} must equal freshly generated bytes")
    if 'ZipFile(file).use' not in helper or 'flatMapIndexed' not in helper:
        errors.append("fingerprints must cover directories and dependency JARs without resolving Gradle state")
    return errors


def main():
    texts = [(ROOT / path).read_text() for path in (PLUGIN, SERVICE, HELPER)]
    if "--self-test" in sys.argv:
        mutations = [(0, 'ignore("docs/00-build.md")', 'ignore("docs/**")'),
                     (0, 'normalizeCommit = name == "test"', 'normalizeCommit = false'),
                     (1, 'id("openbank.test-provenance")', ''),
                     (0, '"pactbroker.url"', '"unrelated.flag"'),
                     (1, 'normalizeCommit = false', 'normalizeCommit = name == "test"'),
                     (1, '== generatedServiceDocs.get().asFile.resolve("docs/00-build.md").readText()', ''),
                     (2, 'ZipFile(file).use', 'skipJarMetadata')]
        for index, old, new in mutations:
            fixture = texts.copy()
            assert old in fixture[index]
            fixture[index] = fixture[index].replace(old, new)
            assert violations(*fixture), f"accepted unsafe mutation: {old}"
        print(f"Provenance cache guard: {len(mutations)} unsafe mutations rejected")
    errors = violations(*texts)
    for error in errors:
        print(f"::error::{error}")
    print("SUBJECTS=7")
    return int(bool(errors))


if __name__ == "__main__":
    raise SystemExit(main())
